mapper.insert:
insert into CHB_MST_COUNTER_PARTY (UUID,COUNTER_ID, COUNTER_TYPE,COUNTER_NAME,REMARK,RELATED_TRADE_STATUS,CREATE_USER, CREATE_DEPT, CREATE_TIME,UPDATE_USER, UPDATE_TIME,COUNTER_TYPE2,STATUS) select * from ( select TEMP.* from (
select #{item.uuid,jdbcType=VARCHAR} UUID, #{item.counterId,jdbcType=VARCHAR} COUNTER_ID, #{item.counterType,jdbcType=VARCHAR} COUNTER_TYPE, #{item.counterName,jdbcType=VARCHAR} COUNTER_NAME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.relatedTradeStatus,jdbcType=VARCHAR} RELATED_TRADE_STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.counterType2,jdbcType=VARCHAR} COUNTER_TYPE2, #{item.status,jdbcType=VARCHAR} STATUS from dual
)TEMP where not EXISTS ( select 1 from CHB_MST_COUNTER_PARTY a where a.COUNTER_ID = TEMP.COUNTER_ID and a.STATUS != 'D' ) ) a;
update CHB_MST_COUNTER_PARTY a,( select * from ( select TEMP.* from (
select #{item.uuid,jdbcType=VARCHAR} UUID, #{item.counterId,jdbcType=VARCHAR} COUNTER_ID, #{item.counterType,jdbcType=VARCHAR} COUNTER_TYPE, #{item.counterName,jdbcType=VARCHAR} COUNTER_NAME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.relatedTradeStatus,jdbcType=VARCHAR} RELATED_TRADE_STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.counterType2,jdbcType=VARCHAR} COUNTER_TYPE2, #{item.status,jdbcType=VARCHAR} STATUS from dual
)TEMP
) a )b set a.COUNTER_TYPE = b.COUNTER_TYPE, a.COUNTER_NAME = b.COUNTER_NAME, a.REMARK = b.REMARK, a.RELATED_TRADE_STATUS = b.RELATED_TRADE_STATUS, a.COUNTER_TYPE2 = b.COUNTER_TYPE2, a.UPDATE_USER = b.UPDATE_USER, a.UPDATE_TIME = b.UPDATE_TIME where a.COUNTER_ID = b.COUNTER_ID and a.STATUS != 'D';
